// A server package published the way many CommonJS packages publish their
// factory: the function is the module (`export =`), and a namespace of the
// same name re-exports it as a named export and as `default`. Both names
// stand for the same function, so an app made through either is one type.
type AliasedServer = typeof server;

declare namespace server {
  export interface Request {
    url: string;
  }

  export interface Reply {
    send(body: unknown): void;
  }

  export type Handler = (request: Request, reply: Reply) => unknown;

  export interface PluginOptions {
    prefix?: string;
    [key: string]: unknown;
  }

  export interface App {
    get(path: string, handler: Handler): App;
    post(path: string, handler: Handler): App;
    /** Runs `plugin` with an app whose routes are served under `options.prefix`. */
    register(plugin: (app: App, options: any) => unknown, options?: PluginOptions): App;
    listen(port: number): void;
  }

  export const server: AliasedServer;
  export { server as default };
}

declare function server(): server.App;

export = server;
